import { useEffect, useState } from "react";

export function TicketSearch({ tickets }: { tickets: Ticket[] }) {
  const [text, setText] = useState("");
  const [query, setQuery] = useState("");

  // Debounce: wait 300 ms after the last keystroke
  useEffect(() => {
    const id = setTimeout(() => setQuery(text), 300);
    return () => clearTimeout(id);
  }, [text]);

  return (
    <>
      <input value={text} onChange={(e) => setText(e.target.value)} />
      {/* 3,000 rows: once this render starts, typing waits */}
      <TicketRows tickets={tickets} query={query} />
    </>
  );
}

import { memo, useDeferredValue, useState } from "react";

// Skips the urgent render: its props haven't changed yet
const SlowRows = memo(TicketRows);

export function TicketSearch({ tickets }: { tickets: Ticket[] }) {
  const [query, setQuery] = useState("");
  const deferredQuery = useDeferredValue(query);
  const isStale = query !== deferredQuery;

  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <div style={{ opacity: isStale ? 0.6 : 1 }}>
        <SlowRows tickets={tickets} query={deferredQuery} />
      </div>
    </>
  );
}

