import { memo, useState, useTransition } from "react";

const SlowRows = memo(TicketRows);

export function TicketFilter({ tickets }: { tickets: Ticket[] }) {
  const [text, setText] = useState("");
  const [query, setQuery] = useState("");
  const [isPending, startTransition] = useTransition();

  function handleChange(value: string) {
    setText(value); // urgent: the input must show it now
    startTransition(() => setQuery(value)); // the list can wait
  }

  return (
    <>
      <input value={text} onChange={(e) => handleChange(e.target.value)} />
      {isPending && <small>Updating…</small>}
      <SlowRows tickets={tickets} query={query} />
    </>
  );
}
